dtsPropsFor.CartaoChecagem:
/** Dados de uma checagem. Datas são objetos Date. */
  artigo: {
    /** Endereço da checagem: o cartão leva a /checagens/<slug>. */
    slug: string;
    titulo: string;
    resumo: string;
    data: Date;
    atualizado?: Date;
    veredito: "verdadeiro" | "impreciso" | "enganoso" | "sem-evidencias" | "falso";
    /** A frase checada. Aceita ==trecho== para o marcador rosa. */
    alegacao: string;
    /** "Nome, qualificação", por exemplo "Jeffrey Chiquini, advogado". */
    autorDaAlegacao: string;
    origem: { plataforma: string; url: string; data?: Date };
    tags: string[];
    fontes: { titulo: string; url: string }[];
    /** true mostra a etiqueta "Rascunho" no cartão. */
    rascunho: boolean;
  };
